const raw = $input.item.json.output[0].content[0].text;
const clean = raw.replace(/```json|```/g, '').trim();
const data = JSON.parse(clean);

return {
  json: {
    especialidad: data.especialidad,
    fecha_deseada: data.fecha_deseada,
    motivo: data.motivo,
    chat_id: $('Telegram Trigger - Solicitud de Turno').item.json.message.chat.id
  }
};

const items = $input.all();
const hayConflicto = items.length > 0 && items[0].json.id !== undefined;

return {
  json: {
    hayConflicto: hayConflicto,
    especialidad: $('Parsear Respuesta IA').item.json.especialidad,
    fecha_deseada: $('Parsear Respuesta IA').item.json.fecha_deseada
  }
};
